/* eslint-disable max-len, max-params */

'use strict';

// MODULES //

var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major' );
var isfinite = require( '@stdlib/math/base/assert/is-finite' );
var Float64Array = require( '@stdlib/array/float64' );
var dgemm = require( '@stdlib/blas/base/dgemm' ).ndarray;
var abs = require( '@stdlib/math/base/special/abs' );
var pow = require( '@stdlib/math/base/special/pow' );
var max = require( '@stdlib/math/base/special/fast/max' );
var workspaceLength = require( './workspace_length.js' );
var winograd = require( './winograd.js' );
var maxAbs = require( './max_abs.js' );
var depth = require( './depth.js' );
var axpby = require( './axpby.js' );


// VARIABLES //

// Operand sums (`S` and `T` matrices) grow by at most a factor of four per recursion level, so sums remain finite whenever `4^L * max(|a|,|b|) <= 2^1021`:
var SUM_LIMIT = pow( 2.0, 1021 );

// Products and output updates are bounded in magnitude by `(10/9) * K * 4.5^L * max(1,|α|) * max|a| * max|b| + |β| * max|c|`, so they remain finite whenever this bound (without the `10/9` factor) is less than `2^1023`:
var PRODUCT_LIMIT = pow( 2.0, 1023 );


// FUNCTIONS //

/**
* Tests whether a provided string indicates to transpose a matrix.
*
* @private
* @param {string} str - input string
* @returns {boolean} boolean indicating whether to transpose a matrix
*
* @example
* var bool = isTransposed( 'transpose' );
* // returns true
*
* @example
* var bool = isTransposed( 'no-transpose' );
* // returns false
*/
function isTransposed( str ) {
	return ( str !== 'no-transpose' );
}


// MAIN //

/**
* Performs the matrix-matrix operation `C = α*op(A)*op(B) + β*C`, where `op(X)` is either `op(X) = X` or `op(X) = X^T`, using the Strassen–Winograd algorithm.
*
* ## Notes
*
* -   Quick returns are identical to those of `dgemm`.
* -   The following cases are delegated to `dgemm` (with the original arguments), thus ensuring bitwise-identical results: problems which would not recurse (i.e., any dimension is less than or equal to the cutoff, or `levels` is zero), `α = 0`, `K = 0`, non-finite `α` or `β`, non-finite elements in `op(A)` or `op(B)` (or in `C` when `β` is nonzero), and magnitudes for which an intermediate result of the fast algorithm could overflow while the conventional algorithm would not.
* -   When `β = 0`, the product `α*op(A)*op(B)` is formed directly in `C`, requiring only the recursion workspace. Otherwise, the product is formed in a temporary matrix having the same memory layout as `C`, which is then combined with `β*C`.
*
* @private
* @param {string} transA - specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param {string} transB - specifies whether `B` should be transposed, conjugate-transposed, or not transposed
* @param {NonNegativeInteger} M - number of rows in the matrix `op(A)` and in the matrix `C`
* @param {NonNegativeInteger} N - number of columns in the matrix `op(B)` and in the matrix `C`
* @param {NonNegativeInteger} K - number of columns in the matrix `op(A)` and number of rows in the matrix `op(B)`
* @param {number} alpha - scalar constant
* @param {Float64Array} A - first matrix
* @param {integer} strideA1 - stride of the first dimension of `A`
* @param {integer} strideA2 - stride of the second dimension of `A`
* @param {NonNegativeInteger} offsetA - starting index for `A`
* @param {Float64Array} B - second matrix
* @param {integer} strideB1 - stride of the first dimension of `B`
* @param {integer} strideB2 - stride of the second dimension of `B`
* @param {NonNegativeInteger} offsetB - starting index for `B`
* @param {number} beta - scalar constant
* @param {Float64Array} C - third matrix
* @param {integer} strideC1 - stride of the first dimension of `C`
* @param {integer} strideC2 - stride of the second dimension of `C`
* @param {NonNegativeInteger} offsetC - starting index for `C`
* @param {PositiveInteger} cutoff - recursion cutoff
* @param {NonNegativeInteger} levels - maximum number of recursion levels
* @returns {Float64Array} `C`
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var B = new Float64Array( [ 1.0, 1.0, 0.0, 1.0 ] );
* var C = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
*
* dgemmsw( 'no-transpose', 'no-transpose', 2, 2, 2, 1.0, A, 2, 1, 0, B, 2, 1, 0, 1.0, C, 2, 1, 0, 1, 4 );
* // C => <Float64Array>[ 2.0, 5.0, 6.0, 11.0 ]
*/
function dgemmsw( transA, transB, M, N, K, alpha, A, strideA1, strideA2, offsetA, B, strideB1, strideB2, offsetB, beta, C, strideC1, strideC2, offsetC, cutoff, levels ) {
	var bound;
	var maxA;
	var maxB;
	var sa1;
	var sa2;
	var sb1;
	var sb2;
	var sp1;
	var sp2;
	var op;
	var L;
	var W;

	if ( M === 0 || N === 0 || ( ( beta === 1.0 ) && ( ( alpha === 0.0 ) || ( K === 0 ) ) ) ) {
		return C;
	}
	L = depth( M, N, K, cutoff, levels );
	if ( L === 0 || alpha === 0.0 || K === 0 || !isfinite( alpha ) || !isfinite( beta ) ) {
		return dgemm( transA, transB, M, N, K, alpha, A, strideA1, strideA2, offsetA, B, strideB1, strideB2, offsetB, beta, C, strideC1, strideC2, offsetC );
	}
	// Resolve transpose operations by swapping strides...
	if ( isTransposed( transA ) ) {
		sa1 = strideA2;
		sa2 = strideA1;
	} else {
		sa1 = strideA1;
		sa2 = strideA2;
	}
	if ( isTransposed( transB ) ) {
		sb1 = strideB2;
		sb2 = strideB1;
	} else {
		sb1 = strideB1;
		sb2 = strideB2;
	}
	// Delegate when the operands contain non-finite values or are large enough that an intermediate result could overflow (a non-finite element yields a `NaN` maximum, which propagates to `bound` and fails the final comparison)...
	maxA = maxAbs( M, K, A, sa1, sa2, offsetA );
	maxB = maxAbs( K, N, B, sb1, sb2, offsetB );
	bound = ( ( maxA*maxB ) * K * pow( 4.5, L ) ) * max( 1.0, abs( alpha ) );
	if ( beta !== 0.0 ) {
		bound += abs( beta ) * maxAbs( M, N, C, strideC1, strideC2, offsetC );
	}
	if ( pow( 4.0, L ) * max( maxA, maxB ) > SUM_LIMIT || !( bound < PRODUCT_LIMIT ) ) {
		return dgemm( transA, transB, M, N, K, alpha, A, strideA1, strideA2, offsetA, B, strideB1, strideB2, offsetB, beta, C, strideC1, strideC2, offsetC );
	}
	if ( beta === 0.0 ) {
		// Form: C = α*op(A)*op(B)
		W = new Float64Array( workspaceLength( M, N, K, cutoff, levels ) );
		return winograd( M, N, K, alpha, A, sa1, sa2, offsetA, B, sb1, sb2, offsetB, C, strideC1, strideC2, offsetC, W, 0, cutoff, levels );
	}
	// Form: P = α*op(A)*op(B), followed by C = P + β*C
	op = M * N;
	W = new Float64Array( op + workspaceLength( M, N, K, cutoff, levels ) );
	if ( isRowMajor( [ strideC1, strideC2 ] ) ) {
		sp1 = N;
		sp2 = 1;
	} else {
		sp1 = 1;
		sp2 = M;
	}
	winograd( M, N, K, alpha, A, sa1, sa2, offsetA, B, sb1, sb2, offsetB, W, sp1, sp2, 0, W, op, cutoff, levels );
	return axpby( M, N, 1.0, W, sp1, sp2, 0, beta, C, strideC1, strideC2, offsetC );
}


// EXPORTS //

module.exports = dgemmsw;
